<template>
  <div class="settings-card">
    <div class="settings-toggle-item-with-selects">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">{{ $t('split') }}</span>
      </div>
      <div class="settings-toggle-selects">
        <q-select
          dense
          outlined
          class="back-white"
          v-model="splittype"
          :options="[
            { label: $t('dont_split'), value: '' },
            { label: $t('split_by_bar_code'), value: 'barcode' },
          ]"
          emit-value
          map-options
          :label="$t('splittype')"
          @update:model-value="splitTypeChanged"
        />
      </div>
    </div>

    <div
      v-if="
        splittype === 'barcode' &&
        Array.isArray(user_settings[split_document_barcode_type])
      "
    >
      <div class="settings-toggle-item-with-selects">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('bar_code_type') }}</span>
        </div>
        <div class="settings-toggle-selects">
          <q-select
            dense
            outlined
            class="back-white"
            v-model="user_settings[split_document_barcode_type]"
            :options="supported_barcode_types"
            emit-value
            use-chips
            multiple
            map-options
            label="Select"
            @update:model-value="
              (val: any) => {
                saveSettings(split_document_barcode_type, val);
              }
            "
          />
        </div>
      </div>

      <div class="settings-toggle-item-with-selects">
        <div class="settings-toggle-content">
          <span class="settings-toggle-label">{{ $t('bar_code_pattern') }}</span>
        </div>
        <div class="settings-toggle-selects">
          <q-input
            dense
            outlined
            tabindex="0"
            class="back-white"
            v-model="user_settings[split_document_barcode_pattern]"
            placeholder="Pattern"
            :error-message="new_model['pattern_error_msg']"
            :error="new_model['pattern_error']"
            @update:model-value="barcodePatternUpdated"
          />
        </div>
        <div class="settings-toggle-actions" v-if="!new_model['regex_validated']">
          <q-btn
            :color="!new_model['regex_validated'] ? 'primary' : 'green'"
            :label="$t('save')"
            @click="validatePattern()"
          />
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { CONSTANTS } from 'src/constants';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import { orgPreferenceApiService } from 'src/services';
import { preferencesService } from 'src/services/preferences/preferencesService';
import { toBoolPreference } from 'src/utils/preferenceBool';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: ['showSpinner'],
  data() {
    return {
      split_document_barcode_pattern: CONSTANTS.SPLIT_DOCUMENT_BARCODE_PATTERN,
      split_document_on_barcode: CONSTANTS.SPLIT_DOCUMENT_ON_BARCODE,
      split_document_barcode_type: CONSTANTS.SPLIT_DOCUMENT_BARCODE_TYPE,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal === false) {
          this.init();
        }
      },
    },
  },
  mounted: function () {
    this.getBarCodeTypes();
    this.setNewModel();
    this.init();
  },
  computed: {},
  methods: {
    init() {
      if (toBoolPreference(this.user_settings[this.split_document_on_barcode])) {
        this.splittype = 'barcode';
      }

      let value = this.user_settings[this.split_document_barcode_type];

      if (typeof value === 'string') {
        this.user_settings[this.split_document_barcode_type] = value
          .split(',')
          .map((v) => v.trim())
          .filter(Boolean);
      } else if (!Array.isArray(value)) {
        this.user_settings[this.split_document_barcode_type] = [];
      }
    },

    setNewModel() {
      this.new_model['regex_validated'] = true;
      this.new_model['pattern_error'] = false;
      this.new_model['pattern_error_msg'] = '';
    },
    barcodePatternUpdated(value: string) {
      if (!this.isPatternEmpty()) {
        this.new_model['regex_validated'] = false;
      }
    },
    async barcodePatternBeforeSave() {
      try {
        this.new_model['regex_validated'] = true;
        if (!this.isPatternEmpty()) {
          this.new_model['regex_validated'] = false;
          this.new_model['pattern_error_msg'] = 'Please validate Pattern';
          this.new_model['pattern_error'] = true;
          return;
        }

        await this.saveBarcodePattern();
        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    async saveBarcodePattern() {
      if (this.isPatternEmpty()) {
        this.user_settings[this.split_document_barcode_pattern] = ' ';
      }
      this.setNewModel();
      await this.saveSettings(
        this.split_document_barcode_pattern,
        this.user_settings[this.split_document_barcode_pattern],
      );
    },
    isPatternEmpty() {
      let is_empty = false;
      if (
        !this.user_settings[this.split_document_barcode_pattern] ||
        this.user_settings[this.split_document_barcode_pattern].trim().length ==
          0
      ) {
        is_empty = true;
      }
      return is_empty;
    },
    async validatePattern() {
      try {
        this.new_model['pattern_error'] = false;
        this.new_model['pattern_error_msg'] = '';
        if (this.isPatternEmpty()) {
          this.new_model['pattern_error_msg'] = 'Pattern is required';
          this.new_model['pattern_error'] = true;
        }

        let response: any;

        let formData = new FormData();
        formData.append(
          'patterns',
          JSON.stringify([
            this.user_settings[this.split_document_barcode_pattern],
          ]),
        );
        response = await orgPreferenceApiService.validatePatterns(formData);

        if (response.data.success === false) {
          throw { message: response.data.message };
        }
        this.updateRows(response.data);
        if (this.new_model['pattern_error']) {
          return;
        }
        await this.saveBarcodePattern();
      } catch (err) {
        logError(err);
        notify.error(
          'Something went wrong while loading data. Please try again.',
        );
      } finally {
      }
    },
    updateRows(result: any) {
      for (let [pattern, validate] of Object.entries(result)) {
        const new_validate = validate === false ? false : true;
        if (new_validate === false) {
          this.new_model['pattern_error_msg'] = 'Valid pattern is required';
          this.new_model['pattern_error'] = true;
        } else {
          this.new_model['regex_validated'] = true;
        }
      }
    },
    splitTypeChanged(new_value: string) {
      this.splittype = new_value;
      if (new_value === 'barcode') {
        this.saveSettings(this.split_document_on_barcode, true);
        this.user_settings[this.split_document_on_barcode] = true;
      } else {
        this.saveSettings(this.split_document_on_barcode, false);
        this.user_settings[this.split_document_on_barcode] = false;
      }
    },
    async getBarCodeTypes() {
      this.showLoading();
      let response: any;

      try {
        response = await orgPreferenceApiService.getSupportedBarcodeTypes();

        if (
          !response ||
          typeof response !== 'object' ||
          Array.isArray(response)
        ) {
          throw { message: this.$t('invalid_barcode_type_response_format') };
        }
        // Convert object entries to dropdown-friendly format
        this.supported_barcode_types = Object.entries(response).map(
          ([key, value]) => ({
            value: key,
            label: value,
          }),
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
    async saveSettings(key: string, value: any) {
      if (!key) {
        return;
      }
      this.showLoading();
      try {
        // setOrgPreference (single-key), not the bulk setOrgPreferences: this
        // component always saves one key at a time, and the singular method
        // routes real booleans (split_document_on_barcode) through the typed
        // SDK endpoint instead of always going through the untyped string
        // bulk endpoint.
        const response = await preferencesService.setOrgPreference(key, value);
        if (!response.success) {
          throw new Error(response.error || 'Failed to save settings');
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    // const user_settings = {} as { [k: string]: any };
    const new_model = {} as { [k: string]: any };
    let data: any = ref([]);

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      // user_settings: ref(user_settings),
      supported_barcode_types: data,
      splittype: ref(''),
      new_model: ref(new_model),

      updateSetting,
      user_settings,
      loading_settings,
    };
  },
});
</script>

<style lang="scss" scoped>
.settings-toggle-selects {
  width: 50% !important;
  min-width: 300px !important;
  flex: 0 0 50% !important;

  :deep(.q-field) {
    width: 100% !important;
  }
}
</style>
