<template>
  <div class="settings-card">
    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('allow_rounding_amount_comparison') }}
          <q-icon
            name="info"
            size="20px"
            class="text-primary cursor-pointer q-ml-sm"
          >
            <q-tooltip anchor="top middle" self="bottom middle">
              {{ $t('amount_rounding_tooltip') }}
            </q-tooltip>
          </q-icon>
        </span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[amount_rounding_setting]"
          @update:model-value="
            (val: any) => {
              saveSettings(amount_rounding_setting, val);
            }
          "
          :disable="user_settings[amount_no_rounding_setting] === true"
        />
      </div>
    </div>

    <div class="settings-toggle-item">
      <div class="settings-toggle-content">
        <span class="settings-toggle-label">
          {{ $t('require_exact_match_amount_comparison') }}
          <q-icon
            name="info"
            size="20px"
            class="text-primary cursor-pointer q-ml-sm"
          >
            <q-tooltip anchor="top middle" self="bottom middle">
              {{ $t('require_exact_amount_comparison_tooltip') }}
            </q-tooltip>
          </q-icon>
        </span>
      </div>
      <div class="settings-toggle-actions">
        <f-toggle size="xs"
          v-model="user_settings[amount_no_rounding_setting]"
          @update:model-value="
            (val: any) => {
              saveSettings(amount_no_rounding_setting, val);
            }
          "
          :disable="user_settings[amount_rounding_setting] === true"
        />
      </div>
    </div>
  </div>
  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import {
  amount_rounding_setting,
  amount_no_rounding_setting,
} from 'src/constants';
import Loader from 'src/components/Loader.vue';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: ['showSpinner'],
  components: {
    Loader,
  },
  data() {
    return {
      amount_rounding_setting,
      amount_no_rounding_setting,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == false && oldVal == true) {
          this.hideLoading();
          this.setDefaultValues();
        } else {
          this.showLoading();
        }
      },
    },
  },
  computed: {},
  mounted: function () {
    this.setDefaultValues();
  },
  methods: {
    async saveSettings(key: string, value: any) {
      if (!key) {
        return false;
      }

      this.showLoading();
      try {
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    /**
     * Set default values for amount rounding and no rounding settings
     */
    setDefaultValues() {
      if (!this.user_settings[this.amount_rounding_setting]) {
        this.user_settings[this.amount_rounding_setting] = false;
      }

      if (!this.user_settings[this.amount_no_rounding_setting]) {
        this.user_settings[this.amount_no_rounding_setting] = false;
      }
    },
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      user_settings,
      updateSetting,
      loading_settings,
    };
  },
});
</script>

<style lang="scss" scoped></style>
