<template>
  <div class="settings-card q-mt-md">
    <div class="full-width">
      <DocBitsTable
        :rows="tableRows"
        :columns="columns"
        row-key="id"
        table-id="supplier_ai_model_table"
        :features="{
          sorting: false,
          filtering: false,
          selection: false,
          bulkActions: false,
          rowActions: isAdmin,
          resizable: false,
          pagination: false,
          columnReorder: false,
          stickyLastColumn: isAdmin,
        }"
        :row-actions="aiRowActions"
        no-data-label="no_data_found"
        flat-style
        @row-action="handleRowAction"
      >
        <template #body-cell-ai_model="{ row }">
          {{ getAiModelLabel(row.ai_model) }}
          <q-tooltip v-if="isAdmin && row.ai_model && row.ai_model !== '-'">
            {{ row.ai_model }}
          </q-tooltip>
        </template>
        <template #body-cell-use_etext_if_available="{ row }">
          <f-toggle size="xs"
            v-model="row.use_etext_if_available"
            :true-value="true"
            :false-value="false"
            :disable="true"
          />
        </template>
      </DocBitsTable>
    </div>

    <q-dialog v-model="deleteConfirm" persistent>
      <q-card>
        <q-card-section
          class="row"
          style="justify-content: center; display: flex"
        >
          <q-avatar icon="warning" color="primary" />
        </q-card-section>

        <q-card-section class="row items-center">
          <span class="q-ml-sm">{{ $t('sure') }}</span>
        </q-card-section>

        <q-card-actions align="right">
          <q-btn
            flat
            :label="$t('cancel')"
            data-cy="cancel"
            color="primary"
            v-close-popup
          />
          <q-btn
            flat
            :label="$t('delete')"
            data-cy="delete-popup"
            color="primary"
            v-close-popup
            @click="deleteTfidfPreferences(deleting_row)"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <Loader />
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { aiModelList } from 'src/constants';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import dateUtils from 'src/utils/date';
import { ApiExceptions } from 'src/exceptions/index';
import { supplierAIModelService } from 'src/services';
import { isTopLevelUserAdmin } from 'src/utils/UserDetails';
import { notify } from 'src/components/notifications/notify';
import { getOrgId } from 'src/utils/organization/org_id_helper';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import type { RowActionItem, UnifiedTableColumn } from 'src/components/Table/types/table/unified-table';

export default defineComponent({
  el: '#app',
  components: { DocBitsTable },
  mixins: [helperMixin, dateUtils],
  data() {
    return {
      isAdmin: ref(false),
    };
  },
  mounted: function () {
    this.isAdmin = isTopLevelUserAdmin();
    this.initializeTfidfContent();
  },
  computed: {},
  methods: {
    initializeTfidfContent() {
      this.tableRows = [];
      this.prepareColumns();
      this.getTfidfPreferences();
    },

    getAiModelLabel(ai_model: string): 'Full' | 'Fast' | 'Turbo' {
      // The table must only ever show a tier label, never a raw model id.
      // Unset/placeholder rows fall back to the backend default tier
      // (Fast = gpt-5.4-mini, the doc2-api DEFAULT_AI_MODEL).
      const DEFAULT_TIER = 'Fast' as const;
      if (!ai_model || ai_model === '-') return DEFAULT_TIER;
      // Strip fine-tune prefix (ft:<base>:<org>::<id>) down to the base model.
      const base = ai_model.startsWith('ft:') ? ai_model.slice(3) : ai_model;
      // Exact current-tier match.
      const match = aiModelList.find((item) => item.value === base);
      if (match) return match.label as 'Full' | 'Fast' | 'Turbo';
      // Legacy stored ids (pre gpt-5.x migration) → tier.
      const legacyTierMap: Partial<Record<string, 'Full' | 'Fast' | 'Turbo'>> = {
        'gpt-4o': 'Full',
        'gpt-4o-mini-2024-07-18': 'Fast',
        'gpt-5': 'Turbo',
      };
      const legacy = legacyTierMap[base];
      if (legacy) return legacy;
      // Unknown / fine-tuned ids: classify by size hint so the cell is still a tier.
      const lower = base.toLowerCase();
      if (lower.includes('nano')) return 'Turbo';
      if (lower.includes('mini')) return 'Fast';
      return 'Full';
    },

    handleRowAction({ action, row }: { action: string; row: any }) {
      if (action === 'delete') {
        this.deleteConfirm = true;
        this.deleting_row = row;
      }
    },
    prepareColumns() {
      this.columns = [
        {
          name: 'supplier_id',
          label: this.$t('supplier_id'),
          align: 'left',
          field: 'supplier_id',
        },
        {
          name: 'ai_model',
          label: this.$t('ai_model'),
          align: 'left',
          field: 'ai_model',
        },
        {
          name: 'use_etext_if_available',
          label: this.$t('wf_module_dropdown_use_etext_if_available').split(
            ' ',
          )[1],
          align: 'left',
          field: 'use_etext_if_available',
        },
        {
          name: 'created_by',
          label: this.$t('created_by'),
          align: 'left',
          field: 'created_by',
        },
        {
          name: 'last_modified_by',
          label: this.$t('modified_by'),
          align: 'left',
          field: 'last_modified_by',
        },
        {
          name: 'created_on',
          label: this.$t('created_on'),
          align: 'left',
          field: 'created_on',
        },
        {
          name: 'last_modified_on',
          label: this.$t('modified'),
          align: 'left',
          field: 'last_modified_on',
        },

      ] as UnifiedTableColumn[];
    },

    async getTfidfPreferences() {
      try {
        let queryParams = { org_id: getOrgId() };
        const response =
          await supplierAIModelService.getTfidfPreferences(queryParams);

        this.tableRows = Object.entries(response).map(([id, dataRows]) => {
          const rows = dataRows as Record<string, any>;
          const processedRow: Record<string, any> = { id };
          // Audit fields come back lowercase from the API (created_on, last_modified_by, …)
          // while preference fields are uppercase (AI_MODEL, SUPPLIER_ID, …).
          const auditFields = ['created_on', 'last_modified_on', 'created_by', 'last_modified_by'];
          this.columns.forEach((col) => {
            // Skip action column as it's UI-only
            if (col.name === 'action') return;
            if (auditFields.includes(col.name)) {
              const value = rows[col.name];
              processedRow[col.name] = col.name.endsWith('_on') ? this.formatDateAccordingToPreference(value) : value ?? '-';
              return;
            }
            processedRow[col.name] = col.name === 'use_etext_if_available' ? String(rows[col.name.toUpperCase()]).toLowerCase() === 'true' : rows[col.name.toUpperCase()] ?? '-';
          });
          return processedRow;
        });
        this.$forceUpdate();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },

    async deleteTfidfPreferences(tfidf_row: any) {
      try {
        this.showLoading();
        let queryParams = { org_id: getOrgId(), tfidf_id: tfidf_row.id };
        const response =
          await supplierAIModelService.deleteTfidfPreference(queryParams);

        if (
          response.hasOwnProperty('success') ||
          response.hasOwnProperty('success') === true
        ) {
          this.tableRows = this.tableRows.filter(
            (item: any) => item.id !== tfidf_row.id,
          );
          notify.success(this.$t('operation_sucessfull'));
          this.$forceUpdate();
        } else {
          throw response;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    return {
      deleteConfirm: ref(false),
      columns: [] as UnifiedTableColumn[],
      tableRows: [] as dynamicObj[],
      deleting_row: ref({} as dynamicObj),
      aiRowActions: [
        { key: 'delete', label: 'delete', icon: 'delete', color: 'negative' },
      ] as RowActionItem[],
    };
  },
});
</script>

<style lang="scss" scoped></style>
