<template>
  <q-card style="width: 600px">
    <form @submit.prevent.stop="submitNewColumFrom">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title
          ><span class="text-weight-bold">{{
            $t('configure_classification_rule')
          }}</span>
        </q-toolbar-title>

        <q-btn flat round dense icon="close" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-pt-none">
        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width"></div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <div
              class="pattern-field"
              :class="{
                'pattern-field--error': new_model['regex_pattern_error'],
              }"
            >
              <q-input
                borderless
                :label="$t('pattern')"
                v-model="new_model['rule_value_1']"
                type="textarea"
                class="full-width pattern-field__input"
              >
                <template v-slot:append>
                  <q-icon
                    v-if="
                      new_model['regex_pattern_error'] ||
                      new_model['regex_duplicate_error']
                    "
                    flat
                    dense
                    name="error"
                    size="24px"
                    color="red"
                  >
                    <q-tooltip class="bg-red line-error-tooltip">
                      <template v-if="new_model['regex_pattern_error']">
                        {{ $t('FIELD_REQUIRED') }}
                      </template>
                      <template v-if="new_model['regex_duplicate_error']">
                        {{ $t('pattern_duplicate_error') }}
                      </template>
                    </q-tooltip>
                  </q-icon>
                </template>
              </q-input>

              <div class="pattern-field__footer">
                <f-toggle
                  v-model="help_expanded"
                  size="xs"
                  left-label
                  :label="
                    help_expanded ? $t('hide_help') : $t('show_help_short')
                  "
                />
              </div>
            </div>
          </div>
        </div>

        <q-slide-transition>
          <div v-show="help_expanded" class="pattern-help-wrapper">
            <div class="pattern-help-panel">
            <div class="pattern-help-panel__title">
              {{ $t('classification_rule_pattern_help_title') }}
            </div>

            <div class="pattern-help-panel__row">
              <span class="pattern-help-panel__badge">O365</span>
              <span class="pattern-help-panel__tokens">
                <code
                  v-for="(tok, i) in splitTokens(
                    $t('classification_rule_pattern_help_o365'),
                  )"
                  :key="i"
                  class="pattern-help-panel__code"
                  >{{ tok }}</code
                >
              </span>
            </div>
            <div class="pattern-help-panel__row">
              <span class="pattern-help-panel__badge">Gmail</span>
              <span class="pattern-help-panel__tokens">
                <code
                  v-for="(tok, i) in splitTokens(
                    $t('classification_rule_pattern_help_gmail'),
                  )"
                  :key="i"
                  class="pattern-help-panel__code"
                  >{{ tok }}</code
                >
              </span>
            </div>

            <q-separator dark class="q-my-xs" />

            <div class="pattern-help-panel__subtitle">
              {{ $t('classification_rule_pattern_help_examples') }}
            </div>
            <div class="pattern-help-panel__example">
              <code class="pattern-help-panel__example-pattern"
                >.*@acme\.de.*</code
              >
              <span class="pattern-help-panel__example-desc">{{
                $t('classification_rule_pattern_help_example_1_desc')
              }}</span>
            </div>
            <div class="pattern-help-panel__example">
              <code class="pattern-help-panel__example-pattern"
                >^ap@acme\.de:.*</code
              >
              <span class="pattern-help-panel__example-desc">{{
                $t('classification_rule_pattern_help_example_2_desc')
              }}</span>
            </div>

            <div class="pattern-help-panel__tip">
              {{ $t('classification_rule_pattern_help_tip') }}
            </div>
            </div>
          </div>
        </q-slide-transition>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              clearable
              outlined
              v-model="new_model['rule_type']"
              use-input
              :options="filteredTypeList"
              @filter="filterTypeListEvent"
              :label="$t('type')"
              emit-value
              map-options
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['rule_type_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    {{ $t('FIELD_REQUIRED') }}
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              clearable
              outlined
              v-model="new_model['sub_org_id']"
              use-input
              :options="filterSubOrgsList"
              @filter="filterSubOrgslistEvent"
              :label="$t('sub_org')"
              :loading="sub_org_list_loading"
              emit-value
              map-options
              popup-content-class="dropdown-fit"
            >
              <template v-slot:option="scope">
                <q-item v-bind="scope.itemProps">
                  <q-item-section>
                    <q-item-label>{{ scope.opt.label }}</q-item-label>
                    <q-tooltip>{{ scope.opt.label }}</q-tooltip>
                  </q-item-section>
                </q-item>
              </template>
              <template v-slot:append>
                <q-icon
                  v-if="new_model['sub_org_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['required_error']">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              clearable
              outlined
              v-model="new_model['doc_type_key']"
              use-input
              :options="filterDocTypeList"
              @filter="filterDocTypeListEvent"
              @update:model-value="new_model['sub_doc_type_key'] = ''"
              emit-value
              map-options
              :label="$t('document_type')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['doc_type_key_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['required_error']">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>

        <div class="row full-width mb-10 mt-8" style="margin-bottom: 20px">
          <div class="full-width">
            <q-select
              clearable
              outlined
              v-model="new_model['sub_doc_type_key']"
              use-input
              :options="SubDocTypeFilteredList"
              @filter="SubDocTypeFilterEvent"
              emit-value
              map-options
              :label="$t('sub_type')"
            >
              <template v-slot:append>
                <q-icon
                  v-if="new_model['doc_type_key_error']"
                  flat
                  dense
                  name="error"
                  size="24px"
                  color="red"
                >
                  <q-tooltip class="bg-red line-error-tooltip">
                    <template v-if="new_model['required_error']">
                      {{ $t('FIELD_REQUIRED') }}
                    </template>
                  </q-tooltip>
                </q-icon>
              </template>
            </q-select>
          </div>
        </div>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />

        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </form>
    <q-inner-loading :showing="loading">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDropdownStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { classificationRulesApiService } from 'src/services';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
  mixins: [helperMixin],
  props: {
    model: {
      type: Object,
    },
    list_data: {
      type: Array,
    },
  },
  components: {},
  data() {
    return {
      message: this.$t('only_characters_spaces'),
      help_expanded: false,
    };
  },
  setup() {
    let model = {} as { [k: string]: any };
    const dropdown_store = useDropdownStore();
    const filterSubOrgsList: any = ref(dropdown_store.subOrgList);
    const filterDocTypeList: any = ref(dropdown_store.doc_type_list);
    const SubDocTypeFilteredList: any = ref([]);
    const filteredTypeList: any = ref(dropdown_store.classification_type_list);

    const {
      doc_type_list,
      sub_types_list,
      subOrgList,
      sub_org_list_loading,
      classification_type_list,
    } = storeToRefs(dropdown_store);

    return {
      filteredTypeList,
      classification_type_list,
      SubDocTypeFilteredList,
      filterDocTypeList,
      subOrgList,
      filterSubOrgsList,
      sub_org_list_loading,
      doc_type_list,
      sub_types_list,
      new_model: ref(model),
      loading: ref(false),
      form_error: ref(''),
    };
  },
  watch: {},
  mounted() {
    this.setNewModel();
  },
  methods: {
    splitTokens(str: string) {
      return (str || '').split(' ').filter((t) => t.length > 0);
    },
    setNewModel() {
      if (this.model) {
        this.new_model['id'] = this.model.id;
        this.new_model['sub_org_id'] = this.model.sub_org_id;
        this.new_model['doc_type_key'] = this.model.doc_type_key;
        this.new_model['sub_doc_type_key'] = this.model.sub_doc_type_key;
        this.new_model['rule_value_1'] = this.model.rule_value_1;
        this.new_model['rule_type'] = this.model.rule_type;
      } else {
        this.new_model['id'] = '';
        this.new_model['sub_org_id'] = '';
        this.new_model['doc_type_key'] = '';
        this.new_model['sub_doc_type_key'] = '';
        this.new_model['rule_value_1'] = '';
        this.new_model['rule_type'] = '';
      }

      this.resetErrors();
    },

    resetErrors() {
      this.new_model['regex_pattern_error'] = false;
      this.new_model['regex_duplicate_error'] = false;
      this.new_model['rule_type_error'] = false;
    },

    filterDocTypeListEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterDocTypeList = this.doc_type_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterDocTypeList = this.doc_type_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    filterSubOrgslistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filterSubOrgsList = this.subOrgList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filterSubOrgsList = this.subOrgList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    filterTypeListEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredTypeList = this.classification_type_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredTypeList = this.classification_type_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    filertByDocTypeKey() {
      if (!this.new_model['doc_type_key']) {
        this.SubDocTypeFilteredList = [];
        return;
      }

      this.SubDocTypeFilteredList = this.sub_types_list.filter((v: any) => {
        return v.doc_type_key == this.new_model['doc_type_key'];
      });
    },

    SubDocTypeFilterEvent(val: string, update: any, abort: any) {
      this.filertByDocTypeKey();
      if (!val) {
        update(() => {
          this.filertByDocTypeKey();
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.SubDocTypeFilteredList = this.SubDocTypeFilteredList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    async submitNewColumFrom() {
      try {
        if (!this.validateRow(this.new_model)) {
          return;
        }
        this.loading = true;
        await this.saveNewRow();

        // close the dialog
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    async saveNewRow() {
      let isUpdate = false;
      try {
        const data: any = {
          doc_type_key: this.new_model['doc_type_key'] || null,
          rule_value_1: this.new_model['rule_value_1'],
          rule_type: this.new_model['rule_type'],
        };

        // Only include the optional sub-fields when they actually have a value.
        if (this.new_model['sub_doc_type_key']) {
          data.sub_doc_type_key = this.new_model['sub_doc_type_key'];
        }
        if (this.new_model['sub_org_id']) {
          data.sub_org_id = this.new_model['sub_org_id'];
        }

        if (this.new_model['id'] != '' && this.new_model['id'] != null) {
          data.id = this.new_model['id'];
          isUpdate = true;
        }

        let response;
        if (isUpdate) {
          response = await classificationRulesApiService.update(data);
        } else {
          response = await classificationRulesApiService.create(data);
          if (!response.id) {
            throw { message: 'Failed to create new record' };
          }
        }

        this.setNewModel();
        const event = new CustomEvent('record_saved', { detail: {} });
        document.dispatchEvent(event);
        notify.success(this.$t('operation_sucessfull'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    validateRow(row: any) {
      let validate = true;
      this.resetErrors();

      const pattern_value = (row['rule_value_1'] || '').trim();
      if (!pattern_value || pattern_value.length == 0) {
        this.new_model['regex_pattern_error'] = true;
        validate = false;
      } else if (Array.isArray(this.list_data) && this.list_data.length > 0) {
        let filterRecord = this.list_data.filter((v: any) => {
          return (
            v.rule_value_1 == pattern_value && this.new_model['id'] !== v.id
          );
        });
        if (filterRecord.length > 0) {
          validate = false;
          this.new_model['regex_duplicate_error'] = true;
        }
      }

      if (!row['rule_type'] || row['rule_type'].length == 0) {
        this.new_model['rule_type_error'] = true;
        validate = false;
      }

      if (!row['sub_org_id'] && !row['doc_type_key']) {
        notify.error(this.$t('empty_sub_org_and_doc_type_error'));
        validate = false;
      }

      return validate;
    },
  },
});
</script>

